// Node 9: Validate Structured JSON from Gemini
const response = $input.first().json;
const leadCapture = $('FastAPI Ingestion (lead-capture)').first().json;
const leadData = $('Normalize Lead Data').first().json;

let parsed = null;
try {
  if (response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
    parsed = JSON.parse(response.candidates[0].content.parts[0].text);
  } else if (response.subject && response.body && response.summary) {
    parsed = response;
  }
} catch (e) {
  return [{
    json: {
      is_valid_ai: false,
      error_reason: 'Malformed JSON returned from Gemini: ' + e.message,
      lead_id: leadCapture.lead_id,
      row_number: leadData.row_number
    }
  }];
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      is_valid_ai: false,
      error_reason: 'Gemini did not return an object',
      lead_id: leadCapture.lead_id,
      row_number: leadData.row_number
    }
  }];
}

const subject = (parsed.subject || '').trim();
const body = (parsed.body || '').trim();
const summary = (parsed.summary || '').trim();

let priority = (parsed.priority || '').trim();
if (!['High', 'Medium', 'Low'].includes(priority)) {
  priority = leadCapture.priority || 'Medium';
}
const priorityReason = (parsed.priority_reason || '').trim() || ('Classified as ' + priority + ' priority by AI qualification.');

if (!subject || !body || !summary) {
  return [{
    json: {
      is_valid_ai: false,
      error_reason: 'Gemini output missing required fields (subject, body, or summary)',
      lead_id: leadCapture.lead_id,
      row_number: leadData.row_number
    }
  }];
}

return [{
  json: {
    is_valid_ai: true,
    lead_id: leadCapture.lead_id,
    subject: subject,
    body: body,
    summary: summary,
    priority: priority,
    priority_reason: priorityReason,
    row_number: leadData.row_number,
    recipient: leadData.email,
    error_reason: null
  }
}];

// Node 12: Check Email Sending Eligibility
// Verifies recipient, subject, body, and ensures lead is eligible for sending.
const draftResponse = $input.first().json;
const leadCapture = $('FastAPI Ingestion (lead-capture)').first().json;
const leadData = $('Normalize Lead Data').first().json;

const recipient = draftResponse.recipient || leadData.email;
const subject = draftResponse.subject;
const body = draftResponse.body;
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!recipient || !emailRegex.test(recipient)) {
  return [{ json: { is_eligible: false, reason: 'Invalid recipient email format', lead_id: leadCapture.lead_id, row_number: leadData.row_number } }];
}

if (!subject || !body) {
  return [{ json: { is_eligible: false, reason: 'Missing email subject or body draft', lead_id: leadCapture.lead_id, row_number: leadData.row_number } }];
}

return [{
  json: {
    is_eligible: true,
    lead_id: leadCapture.lead_id,
    row_number: leadData.row_number,
    recipient: recipient,
    subject: subject,
    body: body,
    priority: draftResponse.priority || leadCapture.priority
  }
}];

// Node 15: Evaluate Gmail Response
// Classifies delivery into Sent, Failed, or Delivery Unknown (ambiguous).
const gmailResult = $input.first().json;
const eligibility = $('Check Email Eligibility').first().json;

// If n8n Gmail node returned an error object
if (gmailResult.error) {
  const errMsg = String(gmailResult.error.message || gmailResult.error);
  const isAmbiguous = errMsg.toLowerCase().includes('timeout') || errMsg.toLowerCase().includes('network') || errMsg.toLowerCase().includes('econnreset');

  return [{
    json: {
      lead_id: eligibility.lead_id,
      row_number: eligibility.row_number,
      recipient: eligibility.recipient,
      subject: eligibility.subject,
      body: eligibility.body,
      priority: eligibility.priority,
      status: isAmbiguous ? 'Delivery Unknown' : 'Failed',
      gmail_message_id: null,
      error_message: errMsg
    }
  }];
}

// Confirmed Gmail message ID returned
const msgId = gmailResult.id || gmailResult.messageId || 'confirmed_msg';
return [{
  json: {
    lead_id: eligibility.lead_id,
    row_number: eligibility.row_number,
    recipient: eligibility.recipient,
    subject: eligibility.subject,
    body: eligibility.body,
    priority: eligibility.priority,
    status: 'Sent',
    gmail_message_id: msgId,
    error_message: null
  }
}];
